1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.jspecify.annotations.Nullable;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
34	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
35	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
36	     * whole key equals an existing owner's.
37	     */
38	    default @Nullable String identityKey(@Nullable Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
43	        String email = owner.getEmail() == null ? "" : owner.getEmail();
44	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
45	        return telephone + "|" + email + "|" + householdId;
46	    }
47	
48	    /**
49	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
50	     * otherwise {@code PHONE}.
51	     */
52	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
57	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
58	    }
59	
60	    /**
61	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
62	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
63	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
64	     * owner has no customerCode.
65	     */
66	    default @Nullable String locality(@Nullable Owner owner) {
67	        if (owner == null) {
68	            return null;
69	        }
70	        String customerCode = owner.getCustomerCode();
71	        if (customerCode == null) {
72	            return "UNKNOWN";
73	        }
74	        int dash = customerCode.indexOf('-');
75	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
76	    }
77	
78	    /**
79	     * Returns the owner's numeric membership level from 1 to 3, computed on creation: starting at 1,
80	     * adding 1 when an email is present and adding 1 when namesakeCount is 0, capped at 3 (level 4 is
81	     * reserved for tenure).
82	     */
83	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        int level = 1;
88	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
89	        if (hasEmail) {
90	            level++;
91	        }
92	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
93	        if (noNamesakes) {
94	            level++;
95	        }
96	        return Math.min(level, 3);
97	    }
98	
99	    /**
100	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
101	     * last two digits of the registrationDate year, e.g. {@code 'MEL-SMI-0007-M26'}.
102	     */
103	    default @Nullable String membershipNumber(@Nullable Owner owner) {
104	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
105	            return null;
106	        }
107	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
108	    }
109	
110	    /**
111	     * Returns the Luhn check digit (0-9) computed over the digits contained in the owner's
112	     * customerCode, or {@code null} when the owner or its customerCode is absent.
113	     */
114	    default @Nullable Integer checkDigit(@Nullable Owner owner) {
115	        if (owner == null || owner.getCustomerCode() == null) {
116	            return null;
117	        }
118	        String s = owner.getCustomerCode();
119	        int sum = 0;
120	        boolean dbl = true;
121	        for (int i = s.length() - 1; i >= 0; i--) {
122	            char c = s.charAt(i);
123	            if (c < '0' || c > '9') {
124	                continue;
125	            }
126	            int d = c - '0';
127	            if (dbl) {
128	                d *= 2;
129	                if (d > 9) {
130	                    d -= 9;
131	                }
132	            }
133	            sum += d;
134	            dbl = !dbl;
135	        }
136	        return (10 - (sum % 10)) % 10;
137	    }
138	
139	    /**
140	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
141	     */
142	    default @Nullable String displayName(@Nullable Owner owner) {
143	        if (owner == null) {
144	            return null;
145	        }
146	        return owner.getLastName() + ", " + owner.getFirstName();
147	    }
148	
149	    /**
150	     * Formats an owner's initials as the upper-cased first letters of firstName and
151	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
152	     */
153	    default @Nullable String initials(@Nullable Owner owner) {
154	        if (owner == null) {
155	            return null;
156	        }
157	        StringBuilder sb = new StringBuilder();
158	        String firstName = owner.getFirstName();
159	        if (firstName != null && !firstName.isEmpty()) {
160	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
161	        }
162	        String lastName = owner.getLastName();
163	        if (lastName != null && !lastName.isEmpty()) {
164	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
165	        }
166	        return sb.toString();
167	    }
168	
169	    Owner toOwner(OwnerDto ownerDto);
170	
171	    @Mapping(target = "id", ignore = true)
172	    @Mapping(target = "pets", ignore = true)
173	    @Mapping(target = "customerCode", ignore = true)
174	    @Mapping(target = "householdId", ignore = true)
175	    @Mapping(target = "namesakeCount", ignore = true)
176	    @Mapping(target = "bulkSignupWarning", ignore = true)
177	    @Mapping(target = "householdSize", ignore = true)
178	    Owner toOwner(OwnerFieldsDto ownerDto);
179	
180	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
181	
182	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
183	
184	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
185	        OwnerPageDto ownerPageDto = new OwnerPageDto();
186	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
187	        ownerPageDto.setPage(ownerPage.getNumber());
188	        ownerPageDto.setSize(ownerPage.getSize());
189	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
190	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
191	        return ownerPageDto;
192	    }
193	}
