49	import org.springframework.samples.petclinic.rest.api.OwnersApi;
50	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
51	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.PetDto;
53	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitDto;
55	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
76	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
77	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
84	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
85	     */
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    /**
122	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
123	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
124	     */
125	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
126	        List<String> missing = new ArrayList<>();
127	        if (isBlank(ownerFieldsDto.getFirstName())) {
128	            missing.add("firstName");
129	        }
130	        if (isBlank(ownerFieldsDto.getLastName())) {
131	            missing.add("lastName");
132	        }
133	        if (isBlank(ownerFieldsDto.getAddress())) {
134	            missing.add("address");
135	        }
136	        if (isBlank(ownerFieldsDto.getCity())) {
137	            missing.add("city");
138	        }
139	        if (isBlank(ownerFieldsDto.getTelephone())) {
140	            missing.add("telephone");
141	        }
142	        if (!missing.isEmpty()) {
143	            throw new RequiredFieldsMissingException(missing);
144	        }
145	    }
146	
147	    private static boolean isBlank(String value) {
148	        return value == null || value.isBlank();
149	    }
150	
151	    /**
152	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
153	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
154	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
155	     * normalized value is what gets stored, returned and used for every address comparison; a value
156	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
157	     * rejects it.
158	     *
159	     * @param address the raw address as supplied by the caller, may be {@code null}
160	     * @return the normalized address ({@code ""} when blank or {@code null})
161	     */
162	    private static String normalizeAddress(String address) {
163	        if (address == null) {
164	            return "";
165	        }
166	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
167	        if (collapsed.isEmpty()) {
168	            return "";
169	        }
170	        String[] tokens = collapsed.split(" ");
171	        StringBuilder sb = new StringBuilder(collapsed.length());
172	        for (int i = 0; i < tokens.length; i++) {
173	            String token = tokens[i];
174	            switch (token) {
175	                case "ST" -> token = "STREET";
176	                case "RD" -> token = "ROAD";
177	                case "AVE" -> token = "AVENUE";
178	                default -> { }
179	            }
180	            if (i > 0) {
181	                sb.append(' ');
182	            }
183	            sb.append(token);
184	        }
185	        return sb.toString();
186	    }
187	
188	    /**
189	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
190	     * A leading {@code +} and its country code are kept as given; otherwise the country code
191	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
192	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
193	     * is recognized the national number must have the exact length that code requires ({@code +61}
194	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
195	     * returned.
196	     *
197	     * @param telephone the raw telephone as supplied by the caller
198	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
199	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
200	     *     national-number length is wrong for its country code
201	     */
202	    private static String normalizeTelephone(String telephone) {
203	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
204	        String e164;
205	        if (cleaned.startsWith("+")) {
206	            e164 = "+" + cleaned.substring(1);
207	        } else {
208	            String national = cleaned;
209	            if (national.startsWith("0")) {
210	                national = national.substring(1);
211	            }
212	            e164 = "+61" + national;
213	        }
214	        String digits = e164.substring(1);
215	        if (!digits.matches("\\d{8,15}")) {
216	            throw new InvalidTelephoneException(
217	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
218	        }
219	        if (digits.startsWith("61")) {
220	            requireNationalLength(digits.substring(2), 9, "+61");
221	        } else if (digits.startsWith("1")) {
222	            requireNationalLength(digits.substring(1), 10, "+1");
223	        }
224	        return e164;
225	    }
226	
227	    /**
228	     * Enforces that the national portion of an E.164 number has the exact number of digits its
229	     * country code requires.
230	     *
231	     * @param national the national-number digits (the part after the country code)
232	     * @param expected the exact national-number length the country code requires
233	     * @param countryCode the country code, for the error message
234	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
235	     */
236	    private static void requireNationalLength(String national, int expected, String countryCode) {
237	        if (national.length() != expected) {
238	            throw new InvalidTelephoneException(
239	                "Telephone with country code '" + countryCode + "' must have " + expected
240	                    + " national digits");
241	        }
242	    }
243	
244	    /**
245	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
246	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
247	     *
248	     * @param email the raw email as supplied by the caller, may be {@code null}
249	     * @return the lower-cased email, or {@code null} when none was supplied
250	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
251	     */
252	    private static String normalizeEmail(String email) {
253	        if (email == null || email.isBlank()) {
254	            return null;
255	        }
256	        String trimmed = email.trim();
257	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
258	            throw new InvalidEmailException("Email must be a syntactically valid address");
259	        }
260	        return trimmed.toLowerCase(Locale.ROOT);
261	    }
262	
263	    /**
264	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
265	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
266	     * householdId}, where the email segment is the empty string when the owner has no email. Because
267	     * the telephone is part of the key, two owners that differ in any one segment (for example two
268	     * members of the same household with different telephones) produce different keys.
269	     *
270	     * @param normalizedTelephone the E.164 telephone of the owner
271	     * @param email the lower-cased email of the owner, may be {@code null}
272	     * @param householdId the stable household identifier of the owner, may be {@code null}
273	     * @return the derived identity key
274	     */
275	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
276	        return (normalizedTelephone == null ? "" : normalizedTelephone)
277	            + "|" + (email == null ? "" : email)
278	            + "|" + (householdId == null ? "" : householdId);
279	    }
280	
281	    /**
282	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
283	     * owner. This one check replaces the former separate telephone, email and household duplicate
284	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
285	     * segment are both allowed. Each existing owner's key is derived from its stored, already
286	     * normalized telephone, email and household identifier.
287	     *
288	     * @param identityKey the derived identity key of the owner being created
289	     * @throws DuplicateIdentityException if another owner already has this identity key
290	     */
291	    private void rejectDuplicateIdentity(String identityKey) {
292	        boolean inUse = this.clinicService.findAllOwners().stream()
293	            .anyMatch(existing -> identityKey.equals(
294	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
295	        if (inUse) {
296	            throw new DuplicateIdentityException(
297	                "An owner with the same identity key already exists");
298	        }
299	    }
300	
301	    /**
302	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
303	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
304	     *
305	     * @param value the raw value, may be {@code null}
306	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
307	     */
308	    private static String normalizeForHousehold(String value) {
309	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
310	    }
311	
312	    /**
313	     * Derives the stable household identifier for an owner from the normalized last name and address.
314	     * The value is a deterministic function of those two fields (compared case-insensitively with
315	     * collapsed whitespace), so every owner in the same
316	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
317	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
318	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
319	     * normalized fields.
320	     *
321	     * @param lastName the last name of the owner being created
322	     * @param address the address of the owner being created
323	     * @return the stable household identifier
324	     */
325	    private static String householdId(String lastName, String address) {
326	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
327	        try {
328	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
329	            StringBuilder sb = new StringBuilder(digest.length * 2);
330	            for (byte b : digest) {
331	                sb.append(String.format("%02x", b));
332	            }
333	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
334	        } catch (NoSuchAlgorithmException e) {
335	            throw new IllegalStateException("SHA-256 not available", e);
336	        }
337	    }
338	
339	    /**
340	     * The maximum number of owners a single city may contain. A create whose city already holds this
341	     * many owners is rejected, so a city never grows beyond this capacity.
342	     */
343	    private static final int CITY_CAPACITY = 50;
344	
345	    /**
346	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
347	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
348	     * trimmed. The count reflects the
349	     * state before the new owner is persisted, so it excludes the owner being created.
350	     *
351	     * @param city the city of the owner being created
352	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
353	     */
354	    private void rejectCityAtCapacity(String city) {
355	        String normalizedCity = normalizeName(city);
356	        long ownersInCity = this.clinicService.findAllOwners().stream()
357	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
358	            .count();
359	        if (ownersInCity >= CITY_CAPACITY) {
360	            throw new CityAtCapacityException(
361	                "The city already contains the maximum number of owners");
362	        }
363	    }
364	
365	    /**
366	     * The maximum number of owners that may be created on a single day. A create made once this many
367	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
368	     * owners are registered per day.
369	     */
370	    private static final int DAILY_OWNER_LIMIT = 100;
371	
372	    /**
373	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
374	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
375	     * rolled forward) registration date of the owner being created. The count reflects the state
376	     * before the new owner is persisted, so it excludes the owner being created.
377	     *
378	     * @param registrationDate the effective business-day registration date of the owner being created
379	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
380	     */
381	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
382	        long ownersToday = this.clinicService.findAllOwners().stream()
383	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
384	            .count();
385	        if (ownersToday >= DAILY_OWNER_LIMIT) {
386	            throw new DailyOwnerLimitExceededException(
387	                "The maximum number of owners for today has already been reached");
388	        }
389	    }
390	
391	    /**
392	     * The number of owners that may already exist for a business day before a create is flagged with
393	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
394	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
395	     */
396	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
397	
398	    /**
399	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
400	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
401	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
402	     * date of the owner being created. The count reflects the state before the new owner is persisted,
403	     * so it excludes the owner being created.
404	     *
405	     * @param registrationDate the effective business-day registration date of the owner being created
406	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
407	     */
408	    private boolean bulkSignupWarning(LocalDate registrationDate) {
409	        long ownersToday = this.clinicService.findAllOwners().stream()
410	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
411	            .count();
412	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
413	    }
414	
415	    /**
416	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
417	     * following Monday, any weekday is returned unchanged.
418	     *
419	     * @param date the effective registration date, supplied or defaulted to the server date
420	     * @return the same date when it is a weekday, otherwise the next Monday
421	     */
422	    private static LocalDate toBusinessDay(LocalDate date) {
423	        DayOfWeek dayOfWeek = date.getDayOfWeek();
424	        if (dayOfWeek == DayOfWeek.SATURDAY) {
425	            return date.plusDays(2);
426	        }
427	        if (dayOfWeek == DayOfWeek.SUNDAY) {
428	            return date.plusDays(1);
429	        }
430	        return date;
431	    }
432	
433	    /**
434	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
435	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
436	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
437	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
438	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
439	     * component: the identity is a pure region-and-hash value.
440	     *
441	     * @param postcode the postcode of the owner being created, may be {@code null}
442	     * @param normalizedTelephone the E.164 telephone of the owner being created
443	     * @param lastName the last name of the owner being created
444	     * @return the formatted customer code
445	     */
446	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
447	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
448	    }
449	
450	    /**
451	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
452	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
453	     * {@code null}, non-numeric, or in no known range.
454	     *
455	     * @param postcode the postcode, may be {@code null}
456	     * @return the region code, or {@code 'UNKNOWN'}
457	     */
458	    private static String regionFromPostcode(String postcode) {
459	        if (postcode == null || postcode.isBlank()) {
460	            return "UNKNOWN";
461	        }
462	        int code;
463	        try {
464	            code = Integer.parseInt(postcode.trim());
465	        } catch (NumberFormatException e) {
466	            return "UNKNOWN";
467	        }
468	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
469	            int[] range = entry.getValue();
470	            if (code >= range[0] && code <= range[1]) {
471	                return entry.getKey();
472	            }
473	        }
474	        return "UNKNOWN";
475	    }
476	
477	    /**
478	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
479	     * upper-cased.
480	     *
481	     * @param value the string to hash
482	     * @param length the number of leading hex characters to return
483	     * @return the upper-cased hex prefix of the digest
484	     */
485	    private static String sha256HexPrefix(String value, int length) {
486	        try {
487	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
488	            StringBuilder sb = new StringBuilder(digest.length * 2);
489	            for (byte b : digest) {
490	                sb.append(String.format("%02x", b));
491	            }
492	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
493	        } catch (NoSuchAlgorithmException e) {
494	            throw new IllegalStateException("SHA-256 not available", e);
495	        }
496	    }
497	
498	    /**
499	     * Counts the existing owners that share the owner-to-be's first and last name, compared
500	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
501	     * new owner is persisted, so it excludes the owner being created.
502	     *
503	     * @param firstName the first name of the owner being created
504	     * @param lastName the last name of the owner being created
505	     * @return the number of existing owners with the same first and last name
506	     */
507	    private int countNamesakes(String firstName, String lastName) {
508	        String normalizedFirstName = normalizeName(firstName);
509	        String normalizedLastName = normalizeName(lastName);
510	        return (int) this.clinicService.findAllOwners().stream()
511	            .filter(existing ->
512	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
513	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
514	            .count();
515	    }
516	
517	    /**
518	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
519	     * number of existing owners already carrying the same {@code householdId}. A household identifier
520	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
521	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
522	     * count includes the owner being created (hence the {@code + 1}).
523	     *
524	     * @param householdId the stable household identifier of the owner being created, or {@code null}
525	     *     when the owner does not share a household
526	     * @return the number of household members after this create (always at least 1)
527	     */
528	    private int householdSize(String householdId) {
529	        if (householdId == null) {
530	            return 1;
531	        }
532	        return (int) this.clinicService.findAllOwners().stream()
533	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
534	            .count() + 1;
535	    }
536	
537	    /**
538	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
539	     * lower-casing.
540	     *
541	     * @param value the raw name, may be {@code null}
542	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
543	     */
544	    private static String normalizeName(String value) {
545	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
546	    }
547	
548	    /**
549	     * The fixed city-to-region table used to validate a postcode against its city
550	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
551	     * therefore accepts any 4-digit postcode.
552	     */
553	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
554	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
555	
556	    /**
557	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
558	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
559	     */
560	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
561	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
562	
563	    /**
564	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
565	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
566	     * when the city maps to a known region, must fall within that region's inclusive range
567	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
568	     * postcode.
569	     *
570	     * @param city the city of the owner being created
571	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
572	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
573	     *     for the city's region
574	     */
575	    private static void validatePostcode(String city, String postcode) {
576	        if (postcode == null || postcode.isBlank()) {
577	            return;
578	        }
579	        if (!postcode.matches("\\d{4}")) {
580	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
581	        }
582	        String region = CITY_REGION.get(city);
583	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
584	        if (range != null) {
585	            int value = Integer.parseInt(postcode);
586	            if (value < range[0] || value > range[1]) {
587	                throw new InvalidPostcodeException(
588	                    "Postcode is out of range for the city's region");
589	            }
590	        }
591	    }
592	
593	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
594	    @Override
595	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
596	        Owner owner = this.clinicService.findOwnerById(ownerId);
597	        if (owner == null) {
598	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
599	        }
600	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
606	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
607	        validateRequiredFields(ownerFieldsDto);
608	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
609	        if (registrationDate == null) {
610	            registrationDate = LocalDate.now();
611	        } else if (registrationDate.isAfter(LocalDate.now())) {
612	            throw new FutureRegistrationDateException(
613	                "registrationDate must not be later than the server date");
614	        }
615	        registrationDate = toBusinessDay(registrationDate);
616	        ownerFieldsDto.setRegistrationDate(registrationDate);
617	        rejectDailyOwnerLimit(registrationDate);
618	        rejectCityAtCapacity(ownerFieldsDto.getCity());
619	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
620	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
621	        ownerFieldsDto.setTelephone(normalizedTelephone);
622	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
623	        ownerFieldsDto.setEmail(normalizedEmail);
624	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
625	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
626	            : null;
627	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
628	        HttpHeaders headers = new HttpHeaders();
629	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
630	        owner.setCustomerCode(customerCode(
631	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
632	        owner.setHouseholdId(ownerHouseholdId);
633	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
634	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
635	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
636	        this.clinicService.saveOwner(owner);
637	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
638	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
639	            ownerMapper.membershipLevel(owner));
640	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
641	        headers.setLocation(UriComponentsBuilder.newInstance()
642	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
643	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
644	    }
645	
646	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
647	    @Override
648	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
649	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
650	        if (currentOwner == null) {
651	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
652	        }
653	        currentOwner.setAddress(ownerFieldsDto.getAddress());
654	        currentOwner.setCity(ownerFieldsDto.getCity());
655	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
656	        currentOwner.setLastName(ownerFieldsDto.getLastName());
657	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
658	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
659	        this.clinicService.saveOwner(currentOwner);
660	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
661	    }
662	
663	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
664	    @Transactional
665	    @Override
666	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
667	        Owner owner = this.clinicService.findOwnerById(ownerId);
668	        if (owner == null) {
669	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
670	        }
671	        this.clinicService.deleteOwner(owner);
672	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
673	    }
674	
675	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
676	    @Override
677	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
678	        Owner owner = this.clinicService.findOwnerById(ownerId);
679	        if (owner == null) {
680	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
681	        }
682	        HttpHeaders headers = new HttpHeaders();
683	        Pet pet = petMapper.toPet(petFieldsDto);
684	        owner.setId(ownerId);
685	        pet.setOwner(owner);
686	        pet.getType().setName(null);
687	        this.clinicService.savePet(pet);
688	        PetDto petDto = petMapper.toPetDto(pet);
689	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
690	            .buildAndExpand(pet.getId()).toUri());
691	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
697	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
698	        if (currentOwner != null) {
699	            Pet currentPet = this.clinicService.findPetById(petId);
700	            if (currentPet != null) {
701	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
702	                currentPet.setName(petFieldsDto.getName());
703	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
704	                this.clinicService.savePet(currentPet);
705	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
706	            }
707	        }
708	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
714	        HttpHeaders headers = new HttpHeaders();
715	        Visit visit = visitMapper.toVisit(visitFieldsDto);
716	        Pet pet = new Pet();
717	        pet.setId(petId);
718	        visit.setPet(pet);
719	        this.clinicService.saveVisit(visit);
720	        VisitDto visitDto = visitMapper.toVisitDto(visit);
721	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
722	            .buildAndExpand(visit.getId()).toUri());
723	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
724	    }
725	
726	
727	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
728	    @Override
729	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
730	        Owner owner = this.clinicService.findOwnerById(ownerId);
731	        if (owner != null) {
732	            Pet pet = owner.getPet(petId);
733	            if (pet != null) {
734	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
735	            }
736	        }
737	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
738	    }
739	}
